import fs from 'node:fs/promises'
import {dir,db,asset,send,reviewed,task} from './reply-runtime-20261007.mjs'
const s=JSON.parse(await fs.readFile(dir+'/reply-refresh.json','utf8'))
const get=name=>{const t=s.threads.find(t=>t.contact.name===name);if(!t)throw Error('Missing '+name);return t}
const stop=get('MICHAEL G. KAVLUK');const peers=await db('market_contacts',{phone:'ilike.*'+stop.contact.phone.slice(-4)+'*'});const same=peers.filter(c=>c.phone?.replace(/\D/g,'').slice(-10)===stop.contact.phone.replace(/\D/g,'').slice(-10));
for(const c of same){await db('market_contacts',{id:'eq.'+c.id},'PATCH',{do_not_contact:true,decision:'opted_out',sequence_paused:true,sequence_paused_reason:'recipient_opt_out',next_follow_up:null,cross_channel_suppressed_at:new Date().toISOString(),cross_channel_suppression_reason:'Recipient explicitly texted Stop on October 7, 2026.'});await db('sequence_jobs',{contact_id:'eq.'+c.id,status:'eq.pending'},'PATCH',{status:'cancelled',error:'Recipient opted out'})}
await reviewed(stop.touches.at(-1).id,'Explicit Stop: DNC and cross-channel suppression saved, pending jobs cancelled. No outbound reply.')
const sim=get('SIM UPPAL');const c=sim.contact;
const plans=[{id:c.id,name:c.name,phone:c.phone,city:c.city,latest:sim.touches.at(-1).id,from:'+14374650584',body:"Hi Sim! We can confirm a flat price once we've reviewed the move details. Even with the new place only 15 minutes away, it depends on the items being moved, the floors at both properties, stairs or elevator access, parking/loading access, and any packing needed. Is the 1-bedroom + den move for you or a client? Would it be okay if I gave you a quick call to go through it?",note:'Owner-directed answer: no guaranteed flat amount before inventory, floors and access review. Asked whether personal/client move and permission for John to call.'}]
for(const name of ['ELLA OROFIAMMA','SAEED POORAKBAR','Paritosh Trehan','DANNY MASTACAN','KAIA TANG','ONKAR GOKHALE']){const t=get(name),c=t.contact,first=name.split(' ')[0].toLowerCase().replace(/^./,x=>x.toUpperCase());plans.push({id:c.id,name,phone:c.phone,city:c.city,latest:t.touches.at(-1).id,from:'+14374650584',body:`Here you go, ${first}! Here's our ${c.city} card. Feel free to save it and share it when a client needs moving help.`,media_urls:[await asset(c.city)]})}
await fs.writeFile(dir+'/1400-reply-plan.json',JSON.stringify(plans,null,2));for(const p of plans)await send(p)
await task(c,'20261007-sim-condo','Sim Uppal: await call permission and move details','Asked flat rate for 1-bedroom + den condo in Mississauga, destination about 15 minutes away. Explained inventory, floors, stairs/elevators, parking/loading and packing must be reviewed before confirming a flat price. Asked if move is for Sim or a client and whether John may call. Await response; no rate or booking promised.')
const michelle=get('MICHELLE BULLMORE');await db('market_contacts',{id:'eq.'+michelle.contact.id},'PATCH',{sequence_paused:true,sequence_paused_reason:'declined_lender_not_realtor',next_follow_up:null});await reviewed(michelle.touches.at(-1).id,'Declined; primarily a lender. Paused outreach and cleared follow-up, no extra message.')
const tammy=get('Tammy Carpenter');await reviewed(tammy.touches.at(-1).id,'Saving our number; acknowledgement only, no extra message.');await db('market_contacts',{id:'eq.'+tammy.contact.id},'PATCH',{sequence_paused:true,sequence_paused_reason:'human_managed_relationship',next_follow_up:null})
const lina=get('LINA FRIDMAN');for(const t of lina.touches.filter(t=>t.direction==='inbound'&&!t.metadata?.partnership_review))await reviewed(t.id,'Reaction reviewed; subsequent explicit card request already fulfilled.')
console.log('Sim replied; 6 requested cards sent; opt-out, decline and acknowledgements handled.')
